# Unset all environment variables related to the vfold code of this process
# directory (generated by 'output --vfold'), and print their names, e.g. to
# go back to the Fortran defaults after 'source vfold/setupVfoldDefaults.sh'
# or after some tests. Source this file:
#   source vfold/unsetVfold.sh
# This unsets:
# - ENV_VFOLD_*: the runtime variables read by the vfold code
# - ENV_VFOLDTEST_*, ENV_FVZ_*: the variables of the tests (vfold/myLaunch.sh)
#   and of the debugging code
# - the old names of the variables of the tests (renamed ENV_VFOLDTEST_* in
#   step 14s, e.g. ENV_NEVENTS) and of the runtime variables (ENV_AV_*)
# - CUDACPP_RUNTIME_BLASCOLORSUM* and CUDACPP_RUNTIME_CUBLASTF32TENSOR*: the
#   cudacpp variables of the BLAS colour sums, also read with a _VFOLD<group>
#   suffix by the vfold cudacpp dispatcher

if [ "${BASH_SOURCE[0]}" == "$0" ]; then
  echo "ERROR! This script must be sourced: source $0"
  exit 1
fi

vfold_vars=$(compgen -e | grep -E '^(ENV_VFOLD_|ENV_VFOLDTEST_|ENV_FVZ_|ENV_AV_|CUDACPP_RUNTIME_BLASCOLORSUM|CUDACPP_RUNTIME_CUBLASTF32TENSOR)|^ENV_(NEVENTS|FOLDING|MCATNLODELTA|PHYSICS|REQACC|ISEED)$')
if [ "${vfold_vars}" == "" ]; then
  echo "MadVfold: no vfold environment variables are set"
else
  echo "MadVfold: unset the vfold environment variables"
  for vfold_var in ${vfold_vars}; do
    echo "unset ${vfold_var}"
    unset ${vfold_var}
  done
fi
unset vfold_vars vfold_var
